// Helpers for extracting canonical markdown sections.
//
// Policy: section boundaries must be located with regular expressions anchored
// to whole heading lines at line start (Investigation Brief 01).

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Returns the content belonging to a markdown section whose heading line is
 * exactly `## <heading>`.
 *
 * The returned string starts after the heading line and ends before the next
 * level-2 heading ("## ") or end-of-file.
 */
function sliceExactH2Section(markdown, headingText) {
  const escaped = escapeRegExp(headingText);
  const startRe = new RegExp(`^## ${escaped}\\s*$`, "m");
  const startMatch = markdown.match(startRe);
  if (!startMatch || startMatch.index == null) return "";

  const afterHeadingIdx = markdown.indexOf("\n", startMatch.index);
  if (afterHeadingIdx < 0) return "";

  const rest = markdown.slice(afterHeadingIdx + 1);
  const nextRe = /^##\s+/m;
  const nextMatch = rest.match(nextRe);
  if (!nextMatch || nextMatch.index == null) return rest;
  return rest.slice(0, nextMatch.index);
}

module.exports = { sliceExactH2Section };
